/**
 * "What to post next" (PROJECT.md section 12 Phase 9).
 *
 * A deliberate decision: these suggestions are DERIVED from the campaign's own
 * performance rather than generated by an LLM. The phase asks for AI
 * suggestions; deriving them has three properties the alternative does not:
 *
 *  - they are free, so opening the campaign page does not need a credit
 *    reservation (AGENTS.md rule 9 says any job that reserves must be a real
 *    job, and a suggestion is not worth a ledger row);
 *  - they are deterministic, so a user who reloads sees the same advice and a
 *    test can assert it;
 *  - they cite the number they came from, which is the difference between
 *    advice and a horoscope.
 *
 * An LLM narrative layer can sit on top later; the data-backed ranking below is
 * what it would have to agree with.
 */

export const POST_TYPES = ['CAPTION', 'POSTER', 'CAROUSEL', 'REEL'] as const;

export type PostType = (typeof POST_TYPES)[number];

export function isPostType(value: string): value is PostType {
  return (POST_TYPES as readonly string[]).includes(value);
}

export interface PerformanceRow {
  type: string;
  platform: string | null;
  likes: number;
  comments: number;
  reach: number;
  clicks: number;
  publishedAt: Date | null;
}

export interface Suggestion {
  type: PostType;
  title: string;
  rationale: string;
}

interface TypeStats {
  type: PostType;
  published: number;
  likes: number;
  comments: number;
  reach: number;
  clicks: number;
  /** (likes + comments) / reach, the comparable number across formats. */
  rate: number;
}

const WEEKDAYS = [
  'Sunday',
  'Monday',
  'Tuesday',
  'Wednesday',
  'Thursday',
  'Friday',
  'Saturday',
] as const;

export function suggestNextPosts(rows: readonly PerformanceRow[]): Suggestion[] {
  // A row with no reach is a publication whose metrics have not arrived yet.
  // Counting it as a zero would drag every average down and make the "best"
  // format the one that was published most recently.
  const measured = rows.filter(
    (row) => row.reach > 0 || row.likes > 0 || row.comments > 0 || row.clicks > 0,
  );

  if (measured.length === 0) {
    return [
      {
        type: 'REEL',
        title: 'Start with a short reel',
        rationale:
          'Video is the format with the widest reach on both connected platforms. There is no performance data for this campaign yet, so start with the format that gives the algorithm the most to work with.',
      },
      {
        type: 'CAROUSEL',
        title: 'Follow with a carousel',
        rationale:
          'Carousels earn saves and repeat views. They are the cheapest way to reuse the reel’s idea without producing new video.',
      },
      {
        type: 'CAPTION',
        title: 'Keep a text post in the mix',
        rationale:
          'A text post costs one generation and keeps the campaign publishing while longer assets are produced.',
      },
    ];
  }

  const byType = new Map<PostType, TypeStats>();

  for (const row of measured) {
    // An unknown type is a data bug, not a suggestion target. Skipping it is
    // better than inventing a format the generator cannot produce.
    if (!isPostType(row.type)) {
      continue;
    }

    const stats = byType.get(row.type) ?? {
      type: row.type,
      published: 0,
      likes: 0,
      comments: 0,
      reach: 0,
      clicks: 0,
      rate: 0,
    };

    stats.published += 1;
    stats.likes += row.likes;
    stats.comments += row.comments;
    stats.reach += row.reach;
    stats.clicks += row.clicks;
    byType.set(row.type, stats);
  }

  const ranked = [...byType.values()]
    .map((stats) => ({ ...stats, rate: engagementRate(stats) }))
    .sort((a, b) => b.rate - a.rate || b.published - a.published);

  const best = ranked[0];

  if (best === undefined) {
    return [];
  }

  const suggestions: Suggestion[] = [
    {
      type: best.type,
      title: `Make another ${label(best.type)}`,
      rationale: `${label(best.type)} is this campaign's strongest format: ${percent(best.rate)} engagement across ${best.published} published ${plural(best.published)}.`,
    },
  ];

  const bestDay = strongestWeekday(measured);

  if (bestDay !== null) {
    suggestions.push({
      type: ranked[1]?.type ?? best.type,
      title: `Schedule the next one for ${WEEKDAYS[bestDay.day]}`,
      rationale: `Posts published on ${WEEKDAYS[bestDay.day]} average ${percent(bestDay.rate)} engagement, the best day in this campaign.`,
    });
  }

  const missing = POST_TYPES.filter((type) => !byType.has(type));

  if (missing[0] !== undefined) {
    suggestions.push({
      type: missing[0],
      title: `Try a ${label(missing[0])}`,
      rationale: `This campaign has no ${label(missing[0])} yet. It is the clearest gap in the mix, and a cheap one to test against the current leader.`,
    });
  } else if (ranked[1] !== undefined) {
    suggestions.push({
      type: ranked[1].type,
      title: `Rotate in a ${label(ranked[1].type)}`,
      rationale: `${label(ranked[1].type)} is second at ${percent(ranked[1].rate)}. Alternating it with ${label(best.type)} keeps the feed varied without abandoning what works.`,
    });
  }

  return suggestions.slice(0, 3);
}

function engagementRate(stats: { likes: number; comments: number; reach: number }): number {
  return stats.reach <= 0 ? 0 : (stats.likes + stats.comments) / stats.reach;
}

function strongestWeekday(rows: readonly PerformanceRow[]): { day: number; rate: number } | null {
  const byDay = new Map<number, { engagement: number; reach: number }>();

  for (const row of rows) {
    if (row.publishedAt === null) {
      continue;
    }

    const day = row.publishedAt.getUTCDay();
    const stats = byDay.get(day) ?? { engagement: 0, reach: 0 };
    stats.engagement += row.likes + row.comments;
    stats.reach += row.reach;
    byDay.set(day, stats);
  }

  let best: { day: number; rate: number } | null = null;

  for (const [day, stats] of byDay) {
    if (stats.reach <= 0) {
      continue;
    }

    const rate = stats.engagement / stats.reach;

    if (best === null || rate > best.rate) {
      best = { day, rate };
    }
  }

  return best;
}

function label(type: PostType): string {
  switch (type) {
    case 'CAPTION':
      return 'caption post';
    case 'POSTER':
      return 'poster';
    case 'CAROUSEL':
      return 'carousel';
    case 'REEL':
      return 'reel';
  }
}

function percent(rate: number): string {
  return `${(rate * 100).toFixed(1)}%`;
}

function plural(count: number): string {
  return count === 1 ? 'post' : 'posts';
}
